function backspaceCompare(s, t) {
  const build = (str) => {
    const stack = [];
    for (const ch of str) {
      if (ch === "#") stack.pop();            // backspace: remove the last character typed
      else stack.push(ch);                    // (popping an empty stack does nothing)
    }
    return stack.join("");
  };
  return build(s) === build(t);
}

