String build(String text) {
    StringBuilder stack = new StringBuilder();   // a StringBuilder makes a fine stack of chars
    for (char ch : text.toCharArray()) {
        if (ch != '#') stack.append(ch);
        else if (stack.length() > 0) stack.deleteCharAt(stack.length() - 1);   // backspace
    }
    return stack.toString();
}

string build(const string& text) {
    string stack;                                // a std::string makes a fine stack of chars
    for (char ch : text) {
        if (ch != '#') stack.push_back(ch);
        else if (!stack.empty()) stack.pop_back();   // backspace
    }
    return stack;
}

bool backspaceCompare(string s, string t) {
    return build(s) == build(t);
}

function backspaceCompare(s, t) {
  let i = s.length - 1, j = t.length - 1;
  let skipS = 0, skipT = 0;                   // backspaces still to apply
  while (i >= 0 || j >= 0) {
    while (i >= 0) {                          // find the next character of s that survives
      if (s[i] === "#") { skipS++; i--; }
      else if (skipS > 0) { skipS--; i--; }
      else break;
    }
    while (j >= 0) {                          // ...and the next one of t
      if (t[j] === "#") { skipT++; j--; }
      else if (skipT > 0) { skipT--; j--; }
      else break;
    }
    if (i >= 0 && j >= 0 && s[i] !== t[j]) return false;   // different surviving characters
    if ((i >= 0) !== (j >= 0)) return false;               // one string has more left
    i--;
    j--;
  }
  return true;
}

