    i, j = len(s) - 1, len(t) - 1
    skip_s = skip_t = 0                   # backspaces still to apply
    while i >= 0 or j >= 0:
        while i >= 0:                     # find the next character of s that survives
            if s[i] == "#":
                skip_s += 1
            elif skip_s > 0:
                skip_s -= 1
            else:
                break
            i -= 1
        while j >= 0:                     # ...and the next one of t
            if t[j] == "#":
                skip_t += 1
            elif skip_t > 0:
                skip_t -= 1
            else:
                break
            j -= 1
        if i >= 0 and j >= 0 and s[i] != t[j]:
            return False                  # different surviving characters
        if (i >= 0) != (j >= 0):
            return False                  # one string has more left
        i -= 1
        j -= 1
    return True

